(function() {
    // Wrap everything in a try...catch to prevent script errors from breaking the UI entirely
    try {
        // --- Find Container Element ---
        const scriptElement = document.currentScript;
        if (!scriptElement) {
            console.error("Card Plugin Error: document.currentScript is not supported or found. Cannot initialize.");
            return;
        }
        // Assume the main container div is the direct previous sibling of the script tag
        const container = scriptElement.previousElementSibling;
        if (!container || !container.classList.contains('card-plugin-container')) {
            console.error("Card Plugin Error: Could not find the container div immediately preceding the script tag.");
            // Fallback: Try searching upwards? Might be too complex/unreliable.
            return;
        }
        console.log("Card Plugin: Container found:", container);

        // --- Get Child Elements (with checks) ---
        const toggleButton = container.querySelector('.plugin-toggle-button');
        const bodyContent = container.querySelector('.card-plugin-body');
        const cardDisplayArea = container.querySelector('.card-display-area');
        const filterButtonsContainer = container.querySelector('.filter-sidebar');

        if (!toggleButton || !bodyContent || !cardDisplayArea || !filterButtonsContainer) {
             console.error("Card Plugin Error: Missing one or more required child elements (toggle, body, display, filter). Check HTML structure.");
             return; // Stop execution if essential elements are missing
        }
        console.log("Card Plugin: All required child elements located.");

        let allCardsData = [];
        const cardDataBlockRaw = `$1`; // The raw captured string

        // --- Log Raw Data ---
        // Log the raw data received to help debug parsing issues
        console.log("Card Plugin: Raw data block ($1) received:\n--START--\n" + cardDataBlockRaw + "\n--END--");

        // --- Data Parsing Function (with error handling) ---
        function parseCardData(block) {
            const cards = [];
            if (!block || !block.trim()) {
                console.warn("Card Plugin Warning: Card data block is empty or whitespace.");
                return cards;
            }
            try {
                const cardRegex = /<card>([\s\S]*?)<\/card>/g;
                let cardMatch;
                while ((cardMatch = cardRegex.exec(block)) !== null) {
                    const cardContent = cardMatch[1];
                    const fieldRegex = /<(\w+)>([\s\S]*?)<\/\1>/g;
                    const card = {};
                    let fieldMatch;
                    while ((fieldMatch = fieldRegex.exec(cardContent)) !== null) {
                        card[fieldMatch[1]] = fieldMatch[2].trim();
                    }

                    // Basic validation: Check if essential fields exist before parsing numbers
                    if (card.cost === undefined || card.atk === undefined || card.hp === undefined || card.name === undefined) {
                        console.warn("Card Plugin Warning: Skipping card due to missing essential fields (cost, atk, hp, name):", cardContent);
                        continue; // Skip this potentially malformed card
                    }

                    card.cost = parseInt(card.cost) || 0; // Default to 0 if parsing fails
                    card.atk = parseInt(card.atk) || 0;
                    card.hp = parseInt(card.hp) || 0;
                    cards.push(card);
                }
                console.log(`Card Plugin: Successfully parsed ${cards.length} cards.`);
            } catch (parseError) {
                console.error("Card Plugin Error: Exception during card data parsing.", parseError, "Block:", block);
            }
            return cards;
        }

        // --- Rendering Function (with error handling) ---
        function renderCards(cardsToRender) {
             cardDisplayArea.innerHTML = ''; // Clear previous content
             if (!cardsToRender || cardsToRender.length === 0) {
                 cardDisplayArea.innerHTML = '<p style="color: #777; width: 100%; text-align: center;">没有符合条件的卡牌。</p>';
                 return;
             }
             try {
                 cardsToRender.forEach(card => {
                     const cardElement = document.createElement('div');
                     cardElement.className = 'card-item';
                     // Use parsed (and potentially defaulted) values
                     const cost = card.cost;
                     const name = card.name || '未知名称';
                     const desc = card.desc || '';
                     const atk = card.atk;
                     const hp = card.hp;

                     cardElement.innerHTML = `
                         <div class="card-cost">${cost}</div>
                         <div class="card-name">${name}</div>
                         <div class="card-desc">${desc}</div>
                         <div class="card-stats">
                             <span class="card-atk">${atk}</span>
                             <span class="card-hp">${hp}</span>
                         </div>
                     `;
                     cardDisplayArea.appendChild(cardElement);
                 });
             } catch (renderError) {
                 console.error("Card Plugin Error: Exception during card element rendering.", renderError);
                 cardDisplayArea.innerHTML = '<p style="color: red; width: 100%; text-align: center;">渲染卡牌时出错！</p>';
             }
        }

        // --- Filtering Function ---
        function filterAndRenderCards(filterValue) {
            console.log(`Card Plugin: Filtering by cost: ${filterValue}`);
            let filteredCards;
            try {
                if (filterValue === 'all') {
                    filteredCards = allCardsData;
                } else if (filterValue === '10+') {
                    filteredCards = allCardsData.filter(card => card.cost >= 10);
                } else {
                    const cost = parseInt(filterValue);
                    if (isNaN(cost)) {
                         console.warn(`Card Plugin Warning: Invalid filter value "${filterValue}". Showing all.`);
                         filteredCards = allCardsData;
                         filterValue = 'all'; // Correct button state later
                    } else {
                         filteredCards = allCardsData.filter(card => card.cost === cost);
                    }
                }
                renderCards(filteredCards);

                // Update active button state
                const buttons = filterButtonsContainer.querySelectorAll('.filter-button');
                buttons.forEach(button => {
                    button.classList.toggle('active', button.dataset.costFilter === filterValue);
                });
            } catch (filterError) {
                 console.error("Card Plugin Error: Exception during filtering/rendering.", filterError);
            }
        }

        // --- Event Listeners ---
        toggleButton.addEventListener('click', () => {
            try {
                const isHidden = bodyContent.style.display === 'none';
                if (isHidden) {
                    bodyContent.style.display = 'flex';
                    toggleButton.textContent = '收起 ▲';
                    // Re-render cards when expanding, applying the current filter
                    const activeFilterButton = filterButtonsContainer.querySelector('.filter-button.active');
                    const currentFilter = activeFilterButton ? activeFilterButton.dataset.costFilter : 'all';
                    filterAndRenderCards(currentFilter);
                } else {
                    bodyContent.style.display = 'none';
                    toggleButton.textContent = '展开 ▼';
                }
            } catch (toggleError) {
                 console.error("Card Plugin Error: Exception during toggle.", toggleError);
            }
        });

        filterButtonsContainer.addEventListener('click', (event) => {
            try {
                if (event.target.classList.contains('filter-button')) {
                    const filterValue = event.target.dataset.costFilter;
                    filterAndRenderCards(filterValue);
                }
            } catch (filterClickError) {
                 console.error("Card Plugin Error: Exception during filter click.", filterClickError);
            }
        });

        // --- Initialization ---
        console.log("Card Plugin: Initializing script...");
        allCardsData = parseCardData(cardDataBlockRaw);
        // Initial render is handled by the first click on the toggle button
        console.log("Card Plugin: Initialization complete. Waiting for expand.");

    } catch (globalError) {
        console.error("Card Plugin Error: Uncaught exception during script setup.", globalError);
        // Attempt to display an error message within the plugin's container if possible
        try {
             const scriptElement = document.currentScript;
             if (scriptElement && scriptElement.previousElementSibling) {
                  const container = scriptElement.previousElementSibling;
                  const displayArea = container.querySelector('.card-display-area');
                  const body = container.querySelector('.card-plugin-body');
                  if (displayArea) {
                      displayArea.innerHTML = '<p style="color: red; font-weight: bold; width: 100%; text-align: center;">卡牌插件脚本初始化失败！<br>请检查浏览器控制台获取详细信息。</p>';
                  }
                   if (body) { // Ensure body is visible to show the error
                       body.style.display = 'flex';
                   }
             }
        } catch (displayErrorError) {
             // If even displaying the error fails, just log it
             console.error("Card Plugin Error: Could not display error message in UI.", displayErrorError);
        }
    }
})();
</script>



