    color: #555;
    margin-bottom: 10px;
    flex-grow: 1;
}
.card-stats {
    display: flex;
    justify-content: space-between;
    margin-top: auto;
}
.card-atk, .card-hp {
    background-color: #e74c3c;
    color: white;
    padding: 4px 8px;
    border-radius: 4px;
    font-size: 0.9em;
    font-weight: bold;
    min-width: 25px;
    text-align: center;
}
.card-hp { background-color: #2ecc71; }
