    display: flex;
    flex-direction: column;
    gap: 8px;
    width: 60px;
    flex-shrink: 0;
}
.filter-button {
    background-color: #a89878;
    color: #fff;
    border: none;
    padding: 8px 0;
    border-radius: 4px;
    cursor: pointer;
    text-align: center;
    font-size: 0.9em;
    transition: background-color 0.2s;
